     */
    static String deriveId(Owner owner) {
        return idFor(owner.getLastName(), owner.getPostcode());
    }

    /**
     * The household id for the given last name and postcode: the first 12 hex characters
     * (upper-cased) of SHA-256 over {@code normalizedLastName + '|' + postcode}. Deterministic, so
     * every member of the same household derives the same id. Returns {@code null} when the
     * postcode is absent or blank.
     */
    static String idFor(String lastName, String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String key = normalize(lastName) + "|" + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02X", b));
            }
            return sb.substring(0, 12);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** The last-name comparison form: trimmed, internal whitespace collapsed, lower-cased. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time uniqueness guard for {@code POST /owners}. It rejects a request with a 409 via
 * {@link DuplicateIdentityException} for an <b>exact identity duplicate</b>: a request whose whole
 * {@link OwnerIdentity identityKey} (normalised telephone, email and household together) equals an
 * existing owner's — a genuinely identical owner is always a duplicate.
 *
 * <p>Sharing a household is no longer a duplicate on its own: several members may belong to the
 * same household (same {@code lastName} and {@code postcode}, see {@link OwnerHousehold}) as long
 * as they differ in telephone or email, so their identity keys differ. A new member's standing is
 * instead bounded by the household level ceiling applied later in the pipeline (see
 * {@link CapMembershipLevel}), not by rejecting the create; a non-declared member is additionally
 * flagged as a <em>possible</em> duplicate (see {@link AssignPossibleDuplicate}).
 *
 * <p>The identity key folds the normalised telephone, email and the last name's Soundex together
 * (see {@link OwnerIdentity}); there is no longer any separate household-derived duplicate check.
 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request's
 * telephone and email are in their stored, canonical forms) and before {@link BuildOwner}. The
 * disposable-email blocklist is applied earlier, in {@link NormalizeOwnerEmail}, so it is enforced
 * before this guard runs.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
                request.getLastName());
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.isDeleted()) {
                continue; // a soft-deleted owner is not a duplicate
            }
            if (identityKey.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link CheckOwnerIdentityUnique} when an owner create request's whole
 * {@link OwnerIdentity identityKey} equals an existing owner's — i.e. the request matches on
 * normalised telephone, email and household together. Checked so it appears in the
 * {@code throws} clause and is routed to its escalation handler, which responds 409.
 */
public class DuplicateIdentityException extends Exception {

    public DuplicateIdentityException(String identityKey) {
        super("An owner with this identity already exists: " + identityKey);
    }
}

package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.function.owner.DuplicateIdentityException;

/**
 * Responds 409 when an owner create request's whole identityKey (normalised telephone, email and
 * household together) is already used by an existing owner.
 */
public class DuplicateIdentityExceptionHandler {

    public void handle(@Parameter DuplicateIdentityException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
                "An owner with this identity already exists");
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
    }
}
